<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/_helper.php';
uks_require_access($pdo);
$id=max(0,(int)($_GET['id']??0));
$st=$pdo->prepare("SELECT uk.*,s.nis,s.nisn,s.nama,s.jk,mk.nama AS kelas,g.nama AS petugas
 FROM uks_kunjungan uk JOIN siswa s ON s.id=uk.siswa_id LEFT JOIN guru g ON g.id=uk.petugas_id LEFT JOIN master_kelas mk ON mk.id=uk.kelas_id
 WHERE uk.id=? LIMIT 1");$st->execute([$id]);$row=$st->fetch();if(!$row)exit('Layanan UKS tidak ditemukan.');
if(!uks_teacher_can_view_student($pdo,(int)$row['siswa_id']))deny_access();
$dr=$pdo->prepare("SELECT uo.jumlah,uo.aturan_pakai,o.nama,o.satuan FROM uks_kunjungan_obat uo JOIN uks_obat o ON o.id=uo.obat_id WHERE uo.kunjungan_id=? ORDER BY uo.id");$dr->execute([$id]);$drugs=$dr->fetchAll();
$rr=$pdo->prepare("SELECT r.*,g.nama AS pendamping_guru FROM uks_rujukan r LEFT JOIN guru g ON g.id=r.pendamping_guru_id WHERE r.kunjungan_id=? LIMIT 1");$rr->execute([$id]);$referral=$rr->fetch();
$sensitive=uks_can_view_sensitive($pdo);
$labels=['baru'=>'BARU','ditangani'=>'DILAYANI','selesai'=>'SELESAI','batal'=>'BATAL'];
$page_title='Detail Layanan UKS';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
