<div class="page-header"><div><h1><i class="bi bi-file-medical-fill"></i> Detail Layanan UKS</h1><p>#<?=e((string)($row['nomor_antrian']??'-'))?> · <?=e($row['tanggal'])?> · <?=e($row['nama'])?></p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>uks/riwayat_layanan.php"><i class="bi bi-arrow-left"></i> Riwayat</a><?php if(uks_can_manage($pdo) && $row['status']!=='batal'):?><a class="btn btn-primary" href="<?=BASE_URL?>uks/kunjungan_edit.php?id=<?=$id?>"><i class="bi bi-pencil-square"></i> Edit</a><?php endif;?></div></div>
<div class="form-card"><h3>Siswa & Status Layanan</h3><div class="detail-grid"><div><small>NIS</small><strong><?=e($row['nis'])?></strong></div><div><small>NISN</small><strong><?=e($row['nisn']??'-')?></strong></div><div><small>Nama</small><strong><?=e($row['nama'])?></strong></div><div><small>Kelas</small><strong><?=e($row['kelas']??'-')?></strong></div><div><small>Status</small><strong><?=e($labels[$row['status']]??$row['status'])?></strong></div><div><small>Keperluan</small><strong><?=e($row['jenis_layanan']??'-')?></strong></div><div><small>Masuk</small><strong><?=e($row['waktu']??'-')?> WIB</strong></div><div><small>Mulai</small><strong><?=e($row['waktu_mulai']??'-')?><?php if($row['waktu_mulai']):?> WIB<?php endif;?></strong></div><div><small>Selesai</small><strong><?=e($row['waktu_selesai']??'-')?><?php if($row['waktu_selesai']):?> WIB<?php endif;?></strong></div><div><small>Petugas</small><strong><?=e($row['petugas']??'-')?></strong></div></div></div>
<?php if($sensitive):?>
<div class="form-card"><h3>Catatan Pelayanan</h3><div class="detail-grid"><div class="full"><small>Keluhan</small><div><?=nl2br(e($row['keluhan']??'-'))?></div></div><div class="full"><small>Hasil Pemeriksaan</small><div><?=nl2br(e($row['hasil_pemeriksaan']??'-'))?></div></div><div class="full"><small>Tindakan</small><div><?=nl2br(e($row['tindakan']??'-'))?></div></div><div class="full"><small>Obat</small><div><?=nl2br(e($row['obat']??'-'))?></div></div><div class="full"><small>Catatan / Tindak Lanjut</small><div><?=nl2br(e($row['catatan']??'-'))?></div></div></div></div>
<div class="form-card"><h3>Obat Terstruktur</h3><div class="table-responsive"><table class="data-table"><thead><tr><th>Obat</th><th>Jumlah</th><th>Satuan</th><th>Aturan Pakai</th></tr></thead><tbody><?php if(!$drugs):?><tr><td colspan="4" class="empty-state">Belum ada obat terstruktur.</td></tr><?php else:foreach($drugs as $d):?><tr><td><?=e($d['nama'])?></td><td><?=e($d['jumlah'])?></td><td><?=e($d['satuan'])?></td><td><?=e($d['aturan_pakai']??'-')?></td></tr><?php endforeach;endif;?></tbody></table></div></div>
<div class="form-card"><h3>Rujukan</h3><?php if($referral):?><div class="referral-box"><strong><?=e(['puskesmas'=>'Puskesmas','rumah_sakit'=>'Rumah Sakit','klinik'=>'Klinik','lainnya'=>'Lainnya'][$referral['tujuan_jenis']]??$referral['tujuan_jenis'])?></strong><span><?=e($referral['fasilitas_nama'])?> · <?=e($referral['tanggal'])?></span><span>Status: <?=e(['direncanakan'=>'Direncanakan','dirujuk'=>'Dirujuk','selesai'=>'Selesai','tidak_jadi'=>'Tidak jadi'][$referral['status']]??$referral['status'])?></span><?php if(uks_can_manage($pdo)):?><a class="btn btn-sm btn-primary" href="<?=BASE_URL?>uks/rujukan.php?id=<?=$referral['id']?>&edit=1">Kelola Rujukan</a><?php endif;?></div><?php else:?><div style="color:#64748b">Belum ada rujukan terstruktur.</div><?php if(uks_can_manage($pdo) && $row['status']!=='batal'):?><div style="margin-top:10px"><a class="btn btn-sm btn-primary" href="<?=BASE_URL?>uks/rujukan.php?kunjungan_id=<?=$id?>"><i class="bi bi-hospital-fill"></i> Tambah Rujukan</a></div><?php endif;?><?php endif;?></div>
<?php else:?><div class="alert alert-info">Informasi detail pelayanan kesehatan dibatasi sesuai hak akses UKS.</div><?php endif;?>
</section></main>
